// ---- trasferte nucleo di Udine ----
var NUCLEO_UD=['villa','scialino','saccomando','vitiello','comugnaro','princi','sangineto','foschiatto','purino','de salvatore','marino','piasentin','vinazza','gabrieli','vitale'];
// luoghi oltre PM Vat (verso Tarvisio), oltre Basiliano (verso Sacile), da San Giovanni al Natisone (verso Trieste)
var TR_SI=['tricesimo','reana','tarcento','artegna','magnano','gemona','gem','osoppo','oso','venzone','carnia','car','moggio','resiutta','chiusaforte','dogna','pontebba','pbba','pbb','ugovizza','ugo','valbruna','camporosso','tarvisio','tar','boscoverde',
  'codroipo','casarsa','pordenone','fontanafredda','sacile','portogruaro','spilimbergo','maniago','cordenons','venezia','mestre','treviso','conegliano',
  'san giovanni al natisone','s. giovanni al natisone','sgn','cormons','capriva','gorizia','sagrado','monfalcone','trieste','ts','umtets'];
// da valutare caso per caso
var TR_VAL=['basiliano','vat','palmanova','cervignano'];
var TR_NOMI={gem:'Gemona',oso:'Osoppo',car:'Carnia',pbba:'Pontebba',pbb:'Pontebba',ugo:'Ugovizza',tar:'Tarvisio/Tarcento',ts:'Trieste',umtets:'Trieste',sgn:'San Giovanni al Natisone','s. giovanni al natisone':'San Giovanni al Natisone',vat:'PM Vat'};
function inNucleo(p){ return NUCLEO_UD.indexOf((p||'').trim().toLowerCase())>=0; }
function trFind(text,list){
  var t=(text||'').toLowerCase();
  for(var i=0;i<list.length;i++){
    var w=list[i].replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    if(new RegExp('(^|[^a-zà-ú])'+w+'(?=[^a-zà-ú]|$)').test(t)) return list[i];
  }
  return null;
}
function trNome(w){ return TR_NOMI[w] || w.replace(/(^|\s)\S/g,function(c){ return c.toUpperCase(); }); }
function trAuto(a){
  var tx=(a.attivita||'')+' '+(a.note||''), w=trFind(tx,TR_SI);
  if(w) return {k:'si',why:trNome(w)};
  w=trFind(tx,TR_VAL); if(w) return {k:'val',why:trNome(w)};
  return {k:'no',why:''};
}
function trInfo(a){ if(a.trasf==='si') return {k:'si',why:'impostata a mano'}; if(a.trasf==='no') return {k:'no',why:'impostata a mano'}; return trAuto(a); }
function trTag(a){
  var i=trInfo(a);
  if(i.k==='si') return '<span class="trtag si">Trasferta'+(i.why?' · '+esc(i.why):'')+'</span>';
  if(i.k==='val') return '<span class="trtag val">Trasferta da valutare · '+esc(i.why)+'</span>';
  return '';
}
function trDay(items){
  var k='no'; items.forEach(function(x){ var i=trInfo(x.a).k; if(i==='si') k='si'; else if(i==='val' && k!=='si') k='val'; }); return k;
}
